postconditions.probe:
base=$(git merge-base HEAD^1 HEAD^2)
test -z "$(comm -23 \
  <(git diff -U0 "$base" HEAD^1 -- deps.lock | awk '
    /^@@ / { if (hunk != "" && !bad) printf "%s", hunk; hunk=""; bad=0; next }
    /^\+/ && !/^\+\+\+/ { hunk = hunk substr($0,2) "\n"; next }
    /^-/ && !/^---/ { bad=1; next }
    END { if (hunk != "" && !bad) printf "%s", hunk }
  ' | sort -u) \
  <(sort -u deps.lock))"

base=$(git merge-base HEAD^1 HEAD^2)
test -z "$(comm -12 \
  <(git diff -U0 "$base" HEAD^1 -- deps.lock | awk '
    /^@@ / { if (hunk != "" && has_minus && !has_plus) printf "%s", hunk; hunk=""; has_plus=0; has_minus=0; next }
    /^\+/ && !/^\+\+\+/ { has_plus=1; next }
    /^-/ && !/^---/ { hunk = hunk substr($0,2) "\n"; has_minus=1; next }
    END { if (hunk != "" && has_minus && !has_plus) printf "%s", hunk }
  ' | sort -u) \
  <(sort -u deps.lock))"
